def read_number(n: int) -> str:
    if n == 0:
        return '영'

    digits = ['영', '일', '이', '삼', '사', '오', '육', '칠', '팔', '구']

    def read_four_digits(num):
        """Read a 4-digit group (0-9999)"""
        if num == 0:
            return ''

        result = ''

        # 천 (thousands) - 1 before 천 is omitted
        thousands = num // 1000
        if thousands > 0:
            if thousands == 1:
                result += '천'
            else:
                result += digits[thousands] + '천'

        # 백 (hundreds) - 1 before 백 is omitted
        hundreds = (num % 1000) // 100
        if hundreds > 0:
            if hundreds == 1:
                result += '백'
            else:
                result += digits[hundreds] + '백'

        # 십 (tens) - 1 before 십 is omitted
        tens = (num % 100) // 10
        if tens > 0:
            if tens == 1:
                result += '십'
            else:
                result += digits[tens] + '십'

        # 일 (ones) - always read the digit (including 1)
        ones = num % 10
        if ones > 0:
            result += digits[ones]

        return result

    # Split into groups: ones, 만, 억
    ones_group = n % 10000
    man_group = (n % 100000000) // 10000
    eok_group = n // 100000000

    result = ''

    # 억 (hundred millions) - always keep number if present
    if eok_group > 0:
        result += read_four_digits(eok_group) + '억'

    # 만 (ten thousands) - special case: if exactly 1, just read as 만
    if man_group > 0:
        if man_group == 1:
            result += '만'
        else:
            result += read_four_digits(man_group) + '만'

    # ones group (no unit)
    if ones_group > 0:
        result += read_four_digits(ones_group)

    return result
